def _get_base_dir():
    """Always returns the folder containing the exe (or script)."""
    if getattr(sys, 'frozen', False):
        return os.path.dirname(sys.executable)   # .exe directory
    return os.path.dirname(os.path.abspath(__file__))

BASE_DIR = _get_base_dir()
ENV_FILE  = os.path.join(BASE_DIR, ".env")

REQUIRED_KEYS = [
    {
        "id": "GROQ_API_KEY",
        "label": "Groq API Key",
        "placeholder": "gsk_...",
        "hint": "Powers AI intelligence, speech-to-text & intent detection.",
        "url": "https://console.groq.com/keys",
        "url_label": "Get free key at console.groq.com",
        "step": "Sign up free \u2192 API Keys \u2192 Create API Key \u2192 Copy",
        "badge": "GROQ",
        "badge_color": "#E8C97A"
    },
    {
        "id": "NEMOTRON_API",
        "label": "NVIDIA NIM / Nemotron Key",
        "placeholder": "nvapi-...",
        "hint": "Powers Vision mode \u2014 live camera & screen AI understanding.",
        "url": "https://build.nvidia.com/nvidia/llama-3_1-nemotron-70b-instruct",
        "url_label": "Get free key at build.nvidia.com",
        "step": "Sign up free \u2192 Get API Key \u2192 Copy the nvapi-... key",
        "badge": "NVIDIA",
        "badge_color": "#E8C97A"
    }
]


def load_env():
    result = {}
    if not os.path.exists(ENV_FILE): return result
    with open(ENV_FILE, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#") or "=" not in line: continue
            k, _, v = line.partition("=")
            result[k.strip()] = v.strip().strip('"').strip("'") 
    return result


def save_env(updates):
    existing = load_env()
    existing.update(updates)
    lines = [f'{k}="{v}"' for k, v in existing.items() if v]
    with open(ENV_FILE, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")


def keys_are_complete():
    env = load_env()
    return all(env.get(k["id"], "").strip() for k in REQUIRED_KEYS)


def apply_env_to_os():
    for k, v in load_env().items():
        if v and k not in os.environ: os.environ[k] = v


SETUP_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8"/>\n<meta name="viewport" content="width=device-width,initial-scale=1"/>\n<title>INNOSTAA — Setup</title>\n<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,300;0,400;0,500;1,300&family=DM+Sans:opsz,wght@9..40,300;9..40,400;9..40,500&family=Syne:wght@400;500;600;700&display=swap" rel="stylesheet"/>\n<style>\n*,*::before,*::after{margin:0;padding:0;box-sizing:border-box;}\n:root{\n  --bg:#0D0C0B;--bg-deep:#090807;--gold:#E8C97A;\n  --gold-soft:rgba(232,201,122,.50);--gold-dim:rgba(232,201,122,.18);\n  --gold-mist:rgba(232,201,122,.07);--gold-line:rgba(232,201,122,.22);\n  --edge:rgba(255,255,255,.065);--edge-h:rgba(255,255,255,.095);\n  --text:#EEE9E0;--text-mid:rgba(238,233,224,.58);\n  --text-low:rgba(238,233,224,.34);--text-dim:rgba(238,233,224,.18);\n  --surf:rgba(255,255,255,.030);--surf-h:rgba(255,255,255,.052);\n  --danger:#B85C48;--success:#7A9E6A;\n}\nhtml,body{width:100%;height:100%;background:var(--bg);color:var(--text);font-family:"DM Sans",sans-serif;overflow:hidden;user-select:none;}\n*{scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.08) transparent;}\n::-webkit-scrollbar{width:3px;}::-webkit-scrollbar-thumb{background:rgba(255,255,255,.08);border-radius:99px;}\n#bgCanvas{position:fixed;inset:0;z-index:0;pointer-events:none;}\n.grid{position:fixed;inset:0;z-index:0;pointer-events:none;\n  background-image:linear-gradient(rgba(255,248,230,.012) 1px,transparent 1px),linear-gradient(90deg,rgba(255,248,230,.012) 1px,transparent 1px);\n  background-size:72px 72px;}\n.wrap{position:relative;z-index:1;width:100vw;height:100vh;display:flex;align-items:center;justify-content:center;}\n.card{\n  width:520px;max-width:96vw;\n  background:linear-gradient(158deg,rgba(255,255,255,.048) 0%,rgba(255,255,255,.014) 50%,rgba(255,255,255,.030) 100%);\n  backdrop-filter:blur(72px) saturate(160%) brightness(1.03);\n  -webkit-backdrop-filter:blur(72px) saturate(160%) brightness(1.03);\n  border:1px solid var(--edge);border-radius:20px;overflow:hidden;\n  box-shadow:0 48px 100px rgba(0,0,0,.72),0 0 0 1px rgba(255,255,255,.03),inset 0 1px 0 rgba(255,255,255,.07);\n  position:relative;animation:cardIn .28s cubic-bezier(.34,1.3,.64,1);\n}\n.card::after{content:"";position:absolute;top:0;left:0;right:0;height:1px;\n  background:linear-gradient(90deg,transparent 8%,rgba(255,255,255,.1) 30%,rgba(255,255,255,.15) 50%,rgba(255,255,255,.1) 70%,transparent 92%);\n  pointer-events:none;}\n.card::before{content:"";position:absolute;bottom:0;left:0;right:0;height:1px;\n  background:linear-gradient(90deg,transparent,rgba(0,0,0,.15),transparent);pointer-events:none;}\n@keyframes cardIn{from{opacity:0;transform:scale(.95)translateY(14px)}to{opacity:1;transform:scale(1)translateY(0)}}\n.card-header{padding:24px 28px 18px;border-bottom:1px solid var(--edge);position:relative;}\n.card-header::after{content:"";position:absolute;bottom:0;left:20%;right:20%;height:1px;\n  background:linear-gradient(90deg,transparent,var(--gold-line),transparent);}\n.logo-row{display:flex;align-items:center;gap:12px;margin-bottom:10px;}\n.logo-img{width:40px;height:40px;border-radius:11px;flex-shrink:0;object-fit:cover;box-shadow:0 4px 16px rgba(0,0,0,.5);}\n.logo-name{font-family:"Cormorant Garamond",serif;font-weight:300;font-size:26px;letter-spacing:8px;text-transform:uppercase;\n  background:linear-gradient(168deg,#fff 0%,var(--gold) 58%,rgba(232,201,122,.6) 100%);\n  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;}\n.setup-tag{font-size:8px;letter-spacing:3.5px;text-transform:uppercase;color:var(--text-dim);font-family:"Syne",sans-serif;\n  margin-top:2px;align-self:flex-end;padding-bottom:4px;}\n.header-sub{font-size:12px;color:var(--text-low);line-height:1.65;}\n.header-sub code{background:rgba(255,255,255,.05);padding:1px 5px;border-radius:4px;font-size:11px;font-family:monospace;color:var(--text-mid);}\n.steps{display:flex;align-items:center;margin:16px 0 0;}\n.step-item{display:flex;align-items:center;gap:6px;}\n.step-dot{width:22px;height:22px;border-radius:50%;border:1px solid var(--edge);background:var(--surf);\n  display:flex;align-items:center;justify-content:center;\n  font-family:"Syne",sans-serif;font-size:9px;font-weight:700;color:var(--text-dim);\n  transition:all .3s;flex-shrink:0;}\n.step-dot.active{border-color:var(--gold-soft);color:var(--gold);background:var(--gold-mist);}\n.step-dot.done{border-color:rgba(122,158,106,.5);color:var(--success);background:rgba(122,158,106,.08);}\n.step-name{font-size:9px;letter-spacing:1.5px;text-transform:uppercase;font-family:"Syne",sans-serif;color:var(--text-dim);transition:color .25s;white-space:nowrap;}\n.step-name.active{color:var(--text-low);}\n.step-name.done{color:var(--success);}\n.step-line{flex:1;height:1px;background:var(--edge);margin:0 10px;transition:background .35s;min-width:20px;}\n.step-line.done{background:rgba(122,158,106,.3);}\n.card-body{padding:18px 28px;display:flex;flex-direction:column;gap:10px;overflow-y:auto;max-height:calc(100vh - 280px);}\n.key-card{background:linear-gradient(158deg,rgba(255,255,255,.038) 0%,rgba(255,255,255,.010) 100%);\n  border:1px solid var(--edge);border-radius:14px;padding:16px 16px 13px;transition:border-color .22s,box-shadow .22s;}\n.key-card.focused{border-color:rgba(255,255,255,.12);}\n.key-card.valid{border-color:rgba(122,158,106,.3);box-shadow:0 0 0 3px rgba(122,158,106,.04);}\n.key-card.invalid{border-color:rgba(184,92,72,.3);}\n.key-top{display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:3px;}\n.key-label{font-family:"Syne",sans-serif;font-size:11px;font-weight:700;color:var(--text);letter-spacing:.4px;}\n.key-badge{font-size:8px;font-weight:700;font-family:"Syne",sans-serif;letter-spacing:1.5px;padding:2px 8px;border-radius:99px;flex-shrink:0;margin-left:8px;}\n.key-hint{font-size:11px;color:var(--text-low);line-height:1.55;margin-bottom:10px;}\n.input-row{display:flex;align-items:center;gap:7px;}\n.key-input{flex:1;background:rgba(255,255,255,.022);border:1px solid var(--edge);border-radius:9px;padding:9px 13px;\n  color:var(--text);font-family:"DM Sans",sans-serif;font-size:13px;outline:none;transition:border-color .2s;user-select:text;}\n.key-input::placeholder{color:var(--text-dim);}\n.key-input:focus{border-color:rgba(255,255,255,.14);}\n.key-input.valid{border-color:rgba(122,158,106,.45);}\n.key-input.invalid{border-color:rgba(184,92,72,.4);}\n.eye-btn{width:32px;height:32px;border-radius:8px;border:1px solid var(--edge);background:var(--surf);\n  cursor:pointer;display:flex;align-items:center;justify-content:center;color:var(--text-dim);flex-shrink:0;transition:all .18s;}\n.eye-btn:hover{background:var(--surf-h);color:var(--text-low);}\n.eye-btn svg{width:13px;height:13px;}\n.status-icon{width:16px;flex-shrink:0;font-size:14px;text-align:center;}\n.link-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:9px;}\n.get-link{display:inline-flex;align-items:center;gap:4px;\n  font-size:10px;color:var(--text-low);font-family:"Syne",sans-serif;font-weight:600;letter-spacing:.3px;\n  background:var(--surf);border:1px solid var(--edge);border-radius:6px;padding:3px 9px;\n  cursor:pointer;transition:all .18s;}\n.get-link:hover{background:var(--surf-h);color:var(--text-mid);}\n.get-link svg{width:9px;height:9px;flex-shrink:0;}\n.step-hint{font-size:10px;color:var(--text-dim);line-height:1.5;}\n.card-footer{display:flex;align-items:center;justify-content:flex-end;gap:10px;\n  padding:14px 28px 20px;border-top:1px solid var(--edge);}\n.saved-msg{font-size:11px;color:var(--success);font-family:"Syne",sans-serif;letter-spacing:.5px;opacity:0;transition:opacity .3s;margin-right:auto;}\n.saved-msg.show{opacity:1;}\n.save-btn{display:inline-flex;align-items:center;gap:7px;\n  background:linear-gradient(135deg,var(--gold),rgba(232,201,122,.72));\n  border:none;border-radius:10px;padding:10px 22px;\n  font-family:"Syne",sans-serif;font-weight:700;font-size:11px;\n  letter-spacing:1px;text-transform:uppercase;color:#0D0C0B;\n  cursor:pointer;transition:all .22s;position:relative;overflow:hidden;\n  box-shadow:0 4px 16px var(--gold-dim);}\n.save-btn::after{content:"";position:absolute;top:-50%;left:-60%;width:40%;height:200%;\n  background:rgba(255,255,255,.15);transform:skewX(-20deg);transition:left .45s;}\n.save-btn:hover:not(:disabled)::after{left:120%;}\n.save-btn:hover:not(:disabled){box-shadow:0 6px 22px var(--gold-dim);transform:translateY(-1px);}\n.save-btn:active:not(:disabled){transform:translateY(0);box-shadow:0 2px 8px var(--gold-dim);}\n.save-btn:disabled{opacity:.22;cursor:not-allowed;box-shadow:none;}\n.save-btn svg{width:13px;height:13px;flex-shrink:0;}\n.toast{position:fixed;bottom:18px;left:50%;transform:translateX(-50%)translateY(12px);\n  background:rgba(14,13,11,.96);border:1px solid var(--edge);border-radius:10px;\n  padding:8px 18px;font-size:11px;color:var(--text-mid);\n  backdrop-filter:blur(40px);opacity:0;transition:all .28s;\n  pointer-events:none;white-space:nowrap;z-index:999;\n  font-family:"Syne",sans-serif;letter-spacing:.5px;}\n.toast.show{opacity:1;transform:translateX(-50%)translateY(0);}\n.toast.ok{border-color:rgba(122,158,106,.3);color:var(--success);}\n.toast.err{border-color:rgba(184,92,72,.3);color:var(--danger);}\n</style>\n</head>\n<body>\n<canvas id="bgCanvas"></canvas>\n<div class="grid"></div>\n<div class="wrap">\n<div class="card">\n  <div class="card-header">\n    <div class="logo-row">\n      <img class="logo-img" src="data:image/png;base64," alt="INNOSTAA"/>\n      <div class="logo-name">INNOSTAA</div>\n      <div class="setup-tag">/ Setup</div>\n    </div>\n    <p class="header-sub">Paste your API keys below. They are saved locally in a <code>.env</code> file and never uploaded anywhere.</p>\n    <div class="steps" id="steps">\n      <div class="step-item"><div class="step-dot active" id="dot-0">1</div><span class="step-name active" id="sn-0">Groq</span></div>\n      <div class="step-line" id="line-0"></div>\n      <div class="step-item"><div class="step-dot" id="dot-1">2</div><span class="step-name" id="sn-1">NVIDIA</span></div>\n      <div class="step-line" id="line-1"></div>\n      <div class="step-item"><div class="step-dot" id="dot-2">&#x2713;</div><span class="step-name" id="sn-2">Launch</span></div>\n    </div>\n  </div>\n  <div class="card-body" id="cardBody"></div>\n  <div class="card-footer">\n    <span class="saved-msg" id="savedMsg">&#x2713; Keys saved!</span>\n    <button class="save-btn" id="saveBtn" onclick="doSave()" disabled>\n      <svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>\n      Save &amp; Launch\n    </button>\n  </div>\n</div>\n</div>\n<div class="toast" id="toast"></div>\n<script>\n(function(){\n  const cv=document.getElementById("bgCanvas");\n  const cx=cv.getContext("2d");\n  let W,H,pts=[];\n  const N=1200;\n  function resize(){W=cv.width=window.innerWidth;H=cv.height=window.innerHeight;pts=[];for(let i=0;i<N;i++)pts.push(mk());}\n  function mk(){const g=Math.random()<.72;const sc=Math.random();const r=sc<.70?Math.random()*.3+.05:sc<.92?Math.random()*.5+.32:Math.random()*.7+.75;return{x:Math.random()*W,y:Math.random()*H,vx:(Math.random()-.5)*.028,vy:(Math.random()-.5)*.018-.004,rot:Math.random()*Math.PI*2,vr:(Math.random()-.5)*.0015,r,ax:.6+Math.random()*.6,ay:.6+Math.random()*.6,a0:Math.random()*.16+.02,tw:Math.random()*.005+.001,ph:Math.random()*Math.PI*2,g};}\n  let f=0;\n  function draw(){f++;cx.clearRect(0,0,W,H);\n    [{x:W*.3,y:H*.45,r:W*.32,a:.018},{x:W*.72,y:H*.6,r:W*.24,a:.014}].forEach(nb=>{\n      const g2=cx.createRadialGradient(nb.x,nb.y,0,nb.x,nb.y,nb.r);\n      g2.addColorStop(0,"rgba(232,201,122,"+nb.a+")");\n      g2.addColorStop(.45,"rgba(232,201,122,"+(nb.a*.3)+")");\n      g2.addColorStop(1,"rgba(0,0,0,0)");\n      cx.fillStyle=g2;cx.fillRect(0,0,W,H);\n    });\n    for(const p of pts){p.x+=p.vx;p.y+=p.vy;p.rot+=p.vr;\n      if(p.x<-4)p.x=W+4;if(p.x>W+4)p.x=-4;if(p.y<-4)p.y=H+4;if(p.y>H+4)p.y=-4;\n      const al=p.a0*(0.22+.78*Math.abs(Math.sin(f*p.tw+p.ph)));\n      cx.save();cx.translate(p.x,p.y);cx.rotate(p.rot);cx.globalAlpha=al;\n      cx.fillStyle=p.g?"#E8C97A":"#1E2B60";\n      cx.beginPath();cx.ellipse(0,0,p.r*p.ax,p.r*p.ay,0,0,Math.PI*2);cx.fill();cx.restore();\n    }\n    requestAnimationFrame(draw);\n  }\n  window.addEventListener("resize",resize);resize();requestAnimationFrame(draw);\n})();\n\nconst KEYS=[{"id": "GROQ_API_KEY", "label": "Groq API Key", "placeholder": "gsk_...", "hint": "Powers AI intelligence, speech-to-text & intent detection.", "url": "https://console.groq.com/keys", "url_label": "Get free key at console.groq.com", "step": "Sign up free \\u2192 API Keys \\u2192 Create API Key \\u2192 Copy", "badge": "GROQ", "badge_color": "#E8C97A"}, {"id": "NEMOTRON_API", "label": "NVIDIA NIM / Nemotron Key", "placeholder": "nvapi-...", "hint": "Powers Vision mode \\u2014 live camera & screen AI understanding.", "url": "https://build.nvidia.com/nvidia/llama-3_1-nemotron-70b-instruct", "url_label": "Get free key at build.nvidia.com", "step": "Sign up free \\u2192 Get API Key \\u2192 Copy the nvapi-... key", "badge": "NVIDIA", "badge_color": "#E8C97A"}];\nconst vals={};\nfunction render(){\n  document.getElementById("cardBody").innerHTML=KEYS.map(k=>`\n    <div class="key-card" id="card-${k.id}">\n      <div class="key-top">\n        <div class="key-label">${k.label}</div>\n        <span class="key-badge" style="color:${k.badge_color};background:${k.badge_color}18;border:1px solid ${k.badge_color}30">${k.badge}</span>\n      </div>\n      <p class="key-hint">${k.hint}</p>\n      <div class="input-row">\n        <input class="key-input" id="inp-${k.id}" type="password" spellcheck="false"\n          placeholder="${k.placeholder}"\n          oninput="onInput(\'${k.id}\')"\n          onfocus="onFocus(\'${k.id}\')"\n          onblur="onBlur(\'${k.id}\')"/>\n        <button class="eye-btn" onclick="toggleShow(\'${k.id}\')" title="Show/hide">\n          <svg fill="none" stroke="currentColor" stroke-width="1.5" viewBox="0 0 24 24">\n            <path stroke-linecap="round" stroke-linejoin="round" d="M2.036 12.322a1.012 1.012 0 010-.639C3.423 7.51 7.36 4.5 12 4.5c4.638 0 8.573 3.007 9.963 7.178.07.207.07.431 0 .639C20.577 16.49 16.64 19.5 12 19.5c-4.638 0-8.573-3.007-9.963-7.178z"/>\n            <path stroke-linecap="round" stroke-linejoin="round" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/>\n          </svg>\n        </button>\n        <span class="status-icon" id="si-${k.id}"></span>\n      </div>\n      <div class="link-row">\n        <span class="get-link" onclick="openUrl(\'${k.url}\')">\n          <svg fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" d="M13.5 6H5.25A2.25 2.25 0 003 8.25v10.5A2.25 2.25 0 005.25 21h10.5A2.25 2.25 0 0018 18.75V10.5m-10.5 6L21 3m0 0h-5.25M21 3v5.25"/></svg>\n          ${k.url_label}\n        </span>\n        <span class="step-hint">&#x24D8; ${k.step}</span>\n      </div>\n    </div>\n  `).join("");\n}\nconst _showing={};\nfunction toggleShow(id){_showing[id]=!_showing[id];document.getElementById("inp-"+id).type=_showing[id]?"text":"password";}\nfunction onInput(id){\n  const v=document.getElementById("inp-"+id).value.trim();\n  vals[id]=v;\n  const ok=v.length>10;\n  const inp=document.getElementById("inp-"+id);\n  const card=document.getElementById("card-"+id);\n  const si=document.getElementById("si-"+id);\n  inp.className="key-input"+(v?(ok?" valid":" invalid"):"");\n  card.className="key-card"+(v?(ok?" valid":" invalid"):"");\n  si.innerHTML=v?(ok?"✓":"✗"):"";\n  si.style.color=ok?"var(--success)":"var(--danger)";\n  updateSteps();updateBtn();\n}\nfunction onFocus(id){const c=document.getElementById("card-"+id);if(!c.classList.contains("valid")&&!c.classList.contains("invalid"))c.classList.add("focused");}\nfunction onBlur(id){document.getElementById("card-"+id).classList.remove("focused");}\nfunction updateSteps(){\n  const n=KEYS.filter(k=>(vals[k.id]||"").length>10).length;\n  KEYS.forEach((k,i)=>{\n    const dot=document.getElementById("dot-"+i);\n    const sn=document.getElementById("sn-"+i);\n    const ln=document.getElementById("line-"+i);\n    if(i<n){dot.className="step-dot done";dot.textContent="\\u2713";sn.className="step-name done";}\n    else if(i===n){dot.className="step-dot active";dot.textContent=i+1;sn.className="step-name active";}\n    else{dot.className="step-dot";dot.textContent=i+1;sn.className="step-name";}\n    if(ln)ln.className="step-line"+(i<n?" done":"");\n  });\n  const fin=document.getElementById("dot-2");\n  const fns=document.getElementById("sn-2");\n  if(n===KEYS.length){fin.className="step-dot done";fns.className="step-name done";}\n  else{fin.className="step-dot";fns.className="step-name";fin.innerHTML="&#x2713;";}\n}\nfunction updateBtn(){document.getElementById("saveBtn").disabled=!KEYS.every(k=>(vals[k.id]||"").length>10);}\nfunction openUrl(url){if(window.pywebview)window.pywebview.api.open_url(url);}\nfunction doSave(){\n  const payload={};\n  KEYS.forEach(k=>{payload[k.id]=vals[k.id]||"";});\n  if(window.pywebview){\n    window.pywebview.api.save_keys(JSON.stringify(payload)).then(ok=>{\n      if(ok){document.getElementById("savedMsg").classList.add("show");showToast("Keys saved! Launching INNOSTAA\\u2026","ok");setTimeout(()=>window.pywebview.api.close_setup(),1200);}\n      else showToast("Save failed \\u2014 check folder permissions.","err");\n    });\n  }\n}\nfunction showToast(msg,cls){\n  const t=document.getElementById("toast");\n  t.textContent=msg;\n  t.className="toast show"+(cls?" "+cls:"");\n  setTimeout(()=>t.className="toast",3200);\n}\nrender();updateSteps();\nwindow.addEventListener("pywebviewready",()=>{\n  window.pywebview.api.get_existing().then(data=>{\n    try{\n      const j=JSON.parse(data);\n      KEYS.forEach(k=>{if(j[k.id]){document.getElementById("inp-"+k.id).value=j[k.id];onInput(k.id);}});\n    }catch(e){}\n  });\n});\n</script>\n</body>\n</html>'


class SetupApi:
    def __init__(self, win_ref):
        self._win = win_ref

    def get_existing(self):
        env = load_env()
        return json.dumps({k["id"]: env.get(k["id"], "") for k in REQUIRED_KEYS})

    def save_keys(self, json_str):
        try:
            data = json.loads(json_str)
            save_env(data)
            for k, v in data.items():
                if v: os.environ[k] = v
            return True
        except Exception as e:
            print(f"[Setup] Save error: {e}")
            return False

    def close_setup(self):
        win = self._win[0]
        if win:
            threading.Thread(target=win.destroy, daemon=True).start()

    def open_url(self, url):
        webbrowser.open(url)


def run():
    win_ref = [None]
    api = SetupApi(win_ref)
    win = webview.create_window(
        "INNOSTAA — Setup",
        html=SETUP_HTML,
        js_api=api,
        width=600, height=640,
        resizable=True,
    )
    win_ref[0] = win
    webview.start(debug=False)
    apply_env_to_os()

if __name__ == "__main__":
    run()